utes,tt.thustartminutes,tt.thuendminutes,tt.fristartminutes,tt.friendminutes\r\n        ,tt.satstartminutes,tt.satendminutes,tt.sunroom,tt.monroom,tt.tueroom,tt.wedroom,tt.thuroom,tt.friroom,tt.satroom,\r\n        luc.alternatecontactid,ac.altname,ac.altemail,ac.altphone,ac.altusername,ac.externalid,ac.altpermissionlevel,\r\n        lucac.alternatecontactid AS secondaryalternatecontactid,\r\n        ac2.altname AS secondaryaltname,ac2.altemail AS secondaryaltemail,ac2.altphone AS secondaryaltphone,\r\n        ac2.altusername AS secondaryaltusername,ac2.externalid AS secondaryexternalid,\r\n        ac2.altpermissionlevel AS secondaryaltpermissionlevel,\r\n        p.firstname,p.lastname,p.student_no,\r\n        scar.StudentCourseAccommodationRequestId,scar.[status] AS rstatus,scar.daterequested AS rdateapproved,\r\n\t\tscar.dateentered AS rdateentered,scar.note1 AS rnote1,scar.note2 AS rnote2\r\nFROM    #tpids t LEFT JOIN courses c ON c.personid=t.personid\r\n        LEFT JOIN lucourses luc ON luc.lucourseid=c.lucourseid\r\n        LEFT JOIN people p ON p.personid=t.personid\r\n        LEFT JOIN people pc ON pc.personid=c.whoadded\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\n        LEFT JOIN lucourseinstructor lci ON lci.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursedata lucd3 ON lucd3.lucoursedataid=lci.instructorid\r\n        LEFT JOIN timetable tt ON tt.timetabletype='C' AND tt.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursealternatecontact ac ON ac.alternatecontactid=luc.alternatecontactid\r\n        LEFT JOIN LuCourseAltContact lucac ON lucac.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursealternatecontact ac2 ON ac2.alternatecontactid=lucac.alternatecontactid\r\n        LEFT JOIN StudentCourseAccommodationRequest scar ON scar.PersonId=c.PersonId AND scar.lucourseid=c.lucourseid\r\nWHERE   (@includedropped=1 OR (c.registratio